const st = (xs) => `$\\{${xs.join(', ')}\\}$`;
const xs16 = range(-320, 320).map((k) => k / 16);

// ================================================================ deck 1 visuals: Cartesian products and relations
const SN = ['Samosa', 'Vada', 'Idli'], DR = ['Tea', 'Lassi'];
const combos = prod(SN, DR);
must(combos.length === 6, 'canteen combos');
const canteen = table(['Snack', 'with Tea', 'with Lassi'], SN.map((s) => [s, ...DR.map((d) => `(${s}, ${d})`)]), 'Table of the six snack and drink combinations in an imagined canteen: Samosa, Vada and Idli each paired with Tea and with Lassi, written as ordered pairs.', 'Every snack paired with every drink: $3 \\times 2 = 6$ ordered pairs.');
const pOrder = plotF({ x: [0, 7], y: [0, 7], pts: [[2, 5, '(2, 5)', 'free'], [5, 2, '(5, 2)', 'free']] }, 'Two points on a grid: (2, 5) is two units across and five up; (5, 2) is five across and two up. They are different points, so the pairs are different.', 'Order matters: $(2, 5) \\ne (5, 2)$.');
const gA = [1, 2, 3], gB = ['x', 'y'];
const gridTable = table(['$A \\backslash B$', '$x$', '$y$'], gA.map((a) => [`$${a}$`, ...gB.map((b) => `$(${a}, ${b})$`)]), 'Grid table for A equal to 1, 2, 3 and B equal to x, y: each row is an element of A, each column an element of B, and each cell is the ordered pair (row, column), six cells in all.', r`$A \times B$ for $A = \{1, 2, 3\}$ and $B = \{x, y\}$: six cells, six pairs.`);
must(prod(gA, gB).length === 6, 'grid');
const nA = [1, 2, 3], nB = [4, 5];
const pGrid = plotF({ x: [0, 4], y: [3, 6], pts: prod(nA, nB).map(([a, b]) => [a, b, `(${a}, ${b})`, 'free']) }, 'Six points on a grid for A equal to 1, 2, 3 and B equal to 4, 5: three columns at x equal to 1, 2, 3 and two rows at y equal to 4 and 5, forming a rectangle of lattice points.', r`The product $\{1, 2, 3\} \times \{4, 5\}$ plotted as points: a $3$ by $2$ lattice.`);
const AB = prod([1, 2], [3, 4]), BA = prod([3, 4], [1, 2]);
must(!sameSet(AB, BA) && AB.length === BA.length, 'AB vs BA');
const abBa = table(['Set', 'Ordered pairs', 'Number'], [[r`$A \times B$`, pl(AB), `$${AB.length}$`], [r`$B \times A$`, pl(BA), `$${BA.length}$`], ['Common pairs', r`$\varnothing$ (none)`, '$0$']], 'Table comparing A cross B and B cross A for A equal to 1, 2 and B equal to 3, 4. Each has four pairs, but the lists are different and have no pair in common.', r`$A = \{1, 2\}$, $B = \{3, 4\}$: same size, different sets.`);
must(AB.filter(([a, b]) => BA.some(([c, d]) => a === c && b === d)).length === 0, 'no common');
const cnt = [[2, 3], [3, 4], [5, 5], [1, 6]].map(([p, q]) => [p, q, prod(range(1, p), range(1, q)).length, prod(range(1, p), range(1, p)).length]);
must(cnt.every(([p, q, pq, pp]) => pq === p * q && pp === p * p), 'counts');
const countTable = table(['$n(A)$', '$n(B)$', '$n(A \\times B)$', '$n(A \\times A)$'], cnt.map((row) => row.map((v) => `$${v}$`)), 'Table of counts: with n(A) and n(B) equal to 2 and 3 there are 6 pairs in A cross B and 4 in A cross A; 3 and 4 give 12 and 9; 5 and 5 give 25 and 25; 1 and 6 give 6 and 1.', r`$n(A \times B) = n(A) \times n(B)$.`);
const WA = [2, 3], WB = [1, 4, 5];
const wAB = prod(WA, WB), wBA = prod(WB, WA), wAA = prod(WA, WA);
must(wAB.length === 6 && wBA.length === 6 && wAA.length === 4, 'WE1 counts');
let we1x = null, we1y = null;
for (const u of range(-20, 20)) for (const v of range(-20, 20)) if (u + 1 === 4 && 2 * v - 3 === 7) { we1x = u; we1y = v; }
must(we1x === 3 && we1y === 5, 'WE1 pair equation');
const we1Table = table(['Product', 'Ordered pairs', 'Count'], [[r`$A \times B$`, pl(wAB), `$${wAB.length}$`], [r`$B \times A$`, pl(wBA), `$${wBA.length}$`], [r`$A \times A$`, pl(wAA), `$${wAA.length}$`]], 'Table of three products for A equal to 2, 3 and B equal to 1, 4, 5: A cross B has six pairs, B cross A has six pairs, and A cross A has four pairs.', r`$A = \{2, 3\}$, $B = \{1, 4, 5\}$.`);
const RA = [1, 2, 3, 4], RB = [1, 3, 5, 7, 9];
const R1 = relFrom(RA, RB, (x, y) => y === 2 * x - 1);
must(R1.length === 4 && sameSet(domOf(R1), RA) && sameSet(rngOf(R1), [1, 3, 5, 7]), 'R1');
const relArrows = arrowDiagram(RA, RB, R1, { A: 'A', B: 'B', alt: 'Arrow diagram of a relation from A equal to 1, 2, 3, 4 to B equal to 1, 3, 5, 7, 9: 1 points to 1, 2 to 3, 3 to 5 and 4 to 7. The element 9 of B receives no arrow.', caption: r`$R = \{(x, y) : y = 2x - 1\}$ from $A$ to $B$.` });
const drTable = table(['Name', 'Meaning', 'For $R$'], [['Domain', 'first entries of the pairs', st(domOf(R1))], ['Codomain', 'the whole target set $B$', st(RB)], ['Range', 'second entries that occur', st(rngOf(R1))]], 'Table of the domain, codomain and range of the relation y equals 2 x minus 1 from A to B: the domain is 1, 2, 3, 4; the codomain is 1, 3, 5, 7, 9; the range is 1, 3, 5, 7.', 'The range is a subset of the codomain: $9$ is never used.');
const waysTable = table(['Form', 'The relation $R$'], [['Roster', pl(R1)], ['Set-builder', r`$\{(x, y) : x \in A,\ y = 2x - 1\}$`], ['Arrow diagram', 'one arrow for each pair (see the previous slide)'], ['Table', r`$x : 1, 2, 3, 4$ and $y : 1, 3, 5, 7$`]], 'Table of four ways to describe the same relation: listing its pairs, a rule in set-builder form, an arrow diagram, or a table of x and y values.', 'One relation, four descriptions.');
const E2A = [0, 1, 2, 3, 4], E2B = [-2, -1, 0, 1, 2, 3, 4];
const E2 = relFrom(E2A, E2B, (x, y) => y === x * x - 3 * x);
must(E2.length === 5 && sameSet(rngOf(E2), [-2, 0, 4]) && isFunctionFrom(E2A, E2), 'E2');
const we2Table = table(['$x$', ...E2A.map((x) => `$${x}$`)], [['$y = x^2 - 3x$', ...E2A.map((x) => `$${x * x - 3 * x}$`)]], 'Table of y equal to x squared minus 3 x for x from 0 to 4: the values are 0, minus 2, minus 2, 0 and 4. Each is in B, so each x gives a pair of R.', r`The range is $\{-2, 0, 4\}$.`);
const cr = [[1, 1], [1, 2], [2, 2], [2, 3]].map(([p, q]) => [p, q, p * q, allRelations(range(1, p), range(1, q)).length]);
must(cr.map((x) => x[3]).join() === '2,4,16,64' && cr.every(([, , pq, n]) => n === 2 ** pq), 'relation counts');
const countRelTable = table(['$n(A)$', '$n(B)$', 'Pairs in $A \\times B$', 'Relations $2^{pq}$'], cr.map((row) => row.map((v) => `$${v}$`)), 'Table counting relations by listing them: with 1 and 1 elements there are 2 relations; 1 and 2 give 4; 2 and 2 give 16; 2 and 3 give 64. The number of pairs is p times q and the number of relations is 2 to the power p q.', 'Counts checked by listing every subset of $A \\times B$.');
const E3X = ['a', 'b', 'c', 'd'], E3Y = [1, 2, 3];
const E3 = [['a', 1], ['a', 2], ['b', 2], ['d', 3]];
must(sameSet(domOf(E3), ['a', 'b', 'd']) && sameSet(rngOf(E3), [1, 2, 3]) && !isFunctionFrom(E3X, E3), 'E3');
const we3Arrows = arrowDiagram(E3X, E3Y, E3, { A: 'X', B: 'Y', alt: 'Arrow diagram of a relation from X equal to a, b, c, d to Y equal to 1, 2, 3: a points to 1 and 2, b to 2, d to 3. The element c has no arrow.', caption: 'The element $c$ has no arrow: it is not in the domain.' });
const summary1 = flow('LR', [['p', 'Ordered pair $(a, b)$'], ['c', r`Cartesian product $A \times B$`], ['r', r`Relation: subset of $A \times B$`], ['d', 'Domain, codomain, range']], [['p', 'c'], ['c', 'r'], ['r', 'd']], 'Summary flow: ordered pairs build the Cartesian product A cross B; a relation is a subset of A cross B; each relation has a domain, a codomain and a range.', 'From pairs to relations.');

// ================================================================ deck 2 visuals: functions and their graphs
const machine = flow('LR', [['i', 'Input $x$'], ['m', 'Rule: add $3$, then double'], ['o', 'Output $f(x)$']], [['i', 'm'], ['m', 'o']], 'Flow diagram of a function as a machine: an input x goes into a rule that adds three and then doubles, and exactly one output f of x comes out.', 'A function: one output for each allowed input.');
const FX = [-2, -1, 1, 2], FY = [1, 4, 9];
const F1 = FX.map((x) => [x, x * x]);
must(isFunctionFrom(FX, F1) && sameSet(rngOf(F1), [1, 4]), 'F1');
const fnArrows = arrowDiagram(FX, FY, F1, { A: 'A', B: 'B', alt: 'Arrow diagram of the squaring function from A equal to minus 2, minus 1, 1, 2 to B equal to 1, 4, 9: minus 2 and 2 go to 4, minus 1 and 1 go to 1. The element 9 of B receives no arrow.', caption: r`$f(x) = x^2$: one arrow from every element of $A$; range $\{1, 4\}$.` });
const N1 = [[1, 'a'], [1, 'b'], [2, 'a']];
must(!isFunctionFrom([1, 2, 3], N1), 'N1');
const notFn = arrowDiagram([1, 2, 3], ['a', 'b'], N1, { A: 'X', B: 'Y', alt: 'Arrow diagram of a relation that is not a function: the element 1 has two arrows, to a and to b, and the element 3 has no arrow at all.', caption: 'Not a function: $1$ has two images and $3$ has none.' });
const pVert = plotF({ x: [-1, 9], y: [-4, 4], fns: [{ expr: 'sqrt(x)', label: r`$y = \sqrt{x}$`, domain: [0, 9] }, { expr: '-sqrt(x)', label: r`$y = -\sqrt{x}$`, domain: [0, 9] }], pts: [[4, 2, '(4, 2)'], [4, -2, '(4, −2)']] }, 'The sideways parabola x equal to y squared drawn as an upper branch y equal to square root of x and a lower branch y equal to minus square root of x. The vertical line x equal to 4 meets it at the two points (4, 2) and (4, minus 2).', r`A vertical line meets $x = y^2$ twice: not a function of $x$.`);
pVert.spec.vlines = [{ x: 4, label: '$x = 4$' }];
// domain and range table: every entry verified by sampling
const g1 = (x) => Math.sqrt(x - 2), g2 = (x) => 1 / (x - 3), g3 = (x) => Math.sqrt(9 - x * x);
const dom = (g) => xs16.filter((x) => Number.isFinite(g(x)));
must(dom(g1).every((x) => x >= 2) && xs16.filter((x) => x >= 2).every((x) => Number.isFinite(g1(x))), 'dom1');
must(dom(g2).length === xs16.length - 1 && !Number.isFinite(g2(3)) && [-4, -0.5, 0.25, 6].every((y) => near(g2(3 + 1 / y), y)) && xs16.every((x) => !Number.isFinite(g2(x)) || g2(x) !== 0), 'dom2/range2');
must(dom(g3).every((x) => Math.abs(x) <= 3) && xs16.filter((x) => Math.abs(x) <= 3).every((x) => Number.isFinite(g3(x))) && [0, 1, 2.5, 3].every((y) => near(g3(Math.sqrt(9 - y * y)), y)), 'dom3/range3');
must(near(g1(2 + 4), 2) && [0, 1, 7].every((y) => near(g1(y * y + 2), y)), 'range1');
const drExamples = table(['Function', 'Domain', 'Range'], [[r`$\sqrt{x - 2}$`, r`$[2, \infty)$`, r`$[0, \infty)$`], [r`$\dfrac{1}{x - 3}$`, r`$\mathbb{R} - \{3\}$`, r`$\mathbb{R} - \{0\}$`], [r`$\sqrt{9 - x^2}$`, '$[-3, 3]$', '$[0, 3]$']], 'Table of three real functions with their domains and ranges: square root of x minus 2 has domain from 2 up and range from 0 up; 1 over x minus 3 has domain all reals except 3 and range all reals except 0; square root of 9 minus x squared has domain minus 3 to 3 and range 0 to 3.', 'Domain from where the rule works; range by solving $y = f(x)$ for $x$.');
const pConst = plotF({ x: [-4, 4], y: [-4, 5], fns: [{ expr: '3', label: '$y = 3$' }, { expr: 'x', label: '$y = x$' }], pts: [[3, 3, '(3, 3)'], [0, 0, '(0, 0)'], [-2, -2, '(−2, −2)']] }, 'A horizontal line y equals 3, the constant function, and the diagonal line y equals x, the identity function. They meet at (3, 3). The diagonal passes through the origin and the point (minus 2, minus 2).', 'Constant: range $\\{3\\}$. Identity: range $\\mathbb{R}$.');
const pPoly = plotF({ x: [-3, 3], y: [-9, 9], fns: [{ expr: 'x^2', label: '$y = x^2$' }, { expr: 'x^3', label: '$y = x^3$' }], pts: [[0, 0, '(0, 0)'], [1, 1, '(1, 1)'], [2, 4, '(2, 4)'], [-2, -8, '(−2, −8)']] }, 'Two polynomial graphs: the U-shaped parabola y equal x squared and the S-shaped cubic y equal x cubed. Both pass through (0, 0) and (1, 1); the parabola passes through (2, 4) and the cubic through (minus 2, minus 8).', r`$x^2$ has range $[0, \infty)$; $x^3$ has range $\mathbb{R}$.`);
const pRat = plotF({ x: [-5, 5], y: [-5, 5], fns: [{ expr: '1/x', label: r`$y = \dfrac{1}{x}$`, domain: [-5, -0.2] }, { expr: '1/x', domain: [0.2, 5] }], pts: [[1, 1, '(1, 1)'], [2, 0.5, '(2, 0.5)'], [-1, -1, '(−1, −1)'], [-2, -0.5, '(−2, −0.5)']] }, 'The graph of y equal 1 over x in two separate branches: one in the first quadrant through (1, 1) and (2, 0.5), one in the third quadrant through (minus 1, minus 1) and (minus 2, minus 0.5). There is no point on the vertical axis.', r`Domain $\mathbb{R} - \{0\}$, range $\mathbb{R} - \{0\}$.`);
const pAbs = plotF({ x: [-4, 4], y: [-1, 5], fns: [{ expr: 'abs(x)', label: '$y = |x|$' }], pts: [[-3, 3, '(−3, 3)'], [0, 0, '(0, 0)'], [3, 3, '(3, 3)']] }, 'The V-shaped graph of y equals the modulus of x, with its corner at the origin and passing through (minus 3, 3) and (3, 3). It never goes below the x-axis.', 'The modulus function: domain $\\mathbb{R}$, range $[0, \\infty)$.');
const pSgn = plotF({ x: [-4, 4], y: [-2, 2], fns: [{ expr: '-1', label: '$y = -1$ for $x < 0$', domain: [-4, -0.05] }, { expr: '1', label: '$y = 1$ for $x > 0$', domain: [0.05, 4] }], pts: [[0, 0, '(0, 0)', 'free'], [-2, -1, '(−2, −1)'], [2, 1, '(2, 1)']] }, 'The signum function: a flat line at height minus 1 for negative x, a single point at the origin where the value is 0, and a flat line at height 1 for positive x.', r`Signum: range $\{-1, 0, 1\}$.`);
const stepsK = [-2, -1, 1, 2, 3];
const pFloor = plotF({ x: [-2.5, 4.5], y: [-3, 4], fns: range(-2, 3).map((k) => ({ expr: String(k), domain: [k, k + 0.99], ...(k === -2 ? { label: '$y = [x]$' } : {}) })), pts: stepsK.map((k) => [k, k, `(${k}, ${k})`.replace('-', '−')]) }, 'The greatest integer function drawn as a staircase of flat steps from x equal to minus 2 up to 4: each step has height equal to its left end, with marked points (minus 2, minus 2), (minus 1, minus 1), (1, 1), (2, 2) and (3, 3).', 'A staircase: $[x]$ jumps by $1$ at every integer.');
must(range(-2, 3).every((k) => fl(k) === k && fl(k + 0.99) === k) && fl(-0.4) === -1 && fl(2.9) === 2, 'floor steps');
const pExp = plotF({ x: [-3, 6], y: [-3, 6], fns: [{ expr: '2^x', label: '$y = 2^x$', domain: [-3, 2.58] }, { expr: 'ln(x)/ln(2)', label: r`$y = \log_2 x$`, domain: [0.125, 6] }], pts: [[0, 1, '(0, 1)'], [1, 2, '(1, 2)'], [2, 4, '(2, 4)'], [1, 0, '(1, 0)'], [2, 1, '(2, 1)'], [4, 2, '(4, 2)']] }, 'Two curves: the rising exponential y equal 2 to the power x through (0, 1), (1, 2) and (2, 4), and the logarithm y equal log base 2 of x through (1, 0), (2, 1) and (4, 2). They are mirror images in the line y equal x.', r`Exponential: domain $\mathbb{R}$, range $(0, \infty)$. Logarithm: domain $(0, \infty)$, range $\mathbb{R}$.`);
must([0, 1, 2].every((x) => 2 ** x === [1, 2, 4][x]) && [[1, 0], [2, 1], [4, 2]].every(([x, y]) => near(Math.log(x) / Math.log(2), y)), 'exp/log points');
const pSemi = plotF({ x: [-4, 4], y: [-1, 4], fns: [{ expr: 'sqrt(9 - x^2)', label: r`$y = \sqrt{9 - x^2}$`, domain: [-3, 3] }], pts: [[0, 3, '(0, 3)'], [1.8, 2.4, '(1.8, 2.4)'], [-1.8, 2.4, '(−1.8, 2.4)']] }, 'The upper half of a circle of radius 3 centred at the origin: the graph of y equals the square root of 9 minus x squared, from x equal to minus 3 to x equal to 3, rising to a top at (0, 3). Marked points include (1.8, 2.4).', r`Domain $[-3, 3]$, range $[0, 3]$.`);
must(near(Math.sqrt(9 - 1.8 ** 2), 2.4) && xs16.filter((x) => Math.abs(x) <= 3).every((x) => g3(x) >= 0 && g3(x) <= 3), 'semicircle');
const pAbs2 = plotF({ x: [-1, 5], y: [-1, 5], fns: [{ expr: 'abs(x - 2) + 1', label: '$y = |x - 2| + 1$' }], pts: [[2, 1, '(2, 1)'], [0, 3, '(0, 3)'], [4, 3, '(4, 3)'], [1, 2, '(1, 2)'], [3, 2, '(3, 2)']] }, 'The V-shaped graph of y equals the modulus of x minus 2, plus 1. Its lowest point is (2, 1); it passes through (1, 2) and (3, 2) on either side, and through (0, 3) and (4, 3). The graph never touches the x-axis.', 'Vertex $(2, 1)$; range $[1, \\infty)$.');
must(near(Math.abs(0 - 2) + 1, 3) && near(Math.abs(3 - 2) + 1, 2) && Math.min(...xs16.map((x) => Math.abs(x - 2) + 1)) === 1, 'abs2');
const ff = (x) => Math.sqrt(x), gg = (x) => x - 4;
const algTable = table(['Combination', 'Rule', 'Domain', 'Value at $x = 9$'], [[r`$f + g$`, r`$\sqrt{x} + x - 4$`, r`$[0, \infty)$`, `$${ff(9) + gg(9)}$`], [r`$f - g$`, r`$\sqrt{x} - x + 4$`, r`$[0, \infty)$`, `$${ff(9) - gg(9)}$`], [r`$fg$`, r`$(x - 4)\sqrt{x}$`, r`$[0, \infty)$`, `$${ff(9) * gg(9)}$`], [r`$\dfrac{f}{g}$`, r`$\dfrac{\sqrt{x}}{x - 4}$`, r`$[0, \infty) - \{4\}$`, r`$\dfrac{3}{5}$`]], 'Table of the four combinations of f of x equal square root of x and g of x equal x minus 4: the sum, difference and product have domain from 0 up, the quotient also excludes 4; at x equal 9 the values are 8, minus 2, 15 and three fifths.', r`$f(x) = \sqrt{x}$ and $g(x) = x - 4$.`);
must(ff(9) === 3 && gg(9) === 5 && ff(9) + gg(9) === 8 && ff(9) - gg(9) === -2 && ff(9) * gg(9) === 15 && near(ff(9) / gg(9), 0.6), 'alg values');
must(xs16.filter((x) => Number.isFinite(ff(x) / gg(x))).every((x) => x >= 0 && x !== 4) && xs16.filter((x) => x >= 0 && x !== 4).every((x) => Number.isFinite(ff(x) / gg(x))), 'quotient domain');
const aF = (x) => Math.sqrt(x - 1), aG = (x) => x - 5;
const we3Table = table(['Item', 'Result'], [[r`Domain of $f + g$ and $fg$`, r`$[1, \infty)$`], [r`Domain of $\dfrac{f}{g}$`, r`$[1, \infty) - \{5\}$`], [r`$(fg)(10)$`, `$${aF(10) * aG(10)}$`], [r`$\left(\dfrac{f}{g}\right)(10)$`, r`$\dfrac{3}{5}$`]], 'Table for f of x equal square root of x minus 1 and g of x equal x minus 5: the sum and product have domain from 1 up, the quotient also excludes 5; at x equal 10 the product is 15 and the quotient is three fifths.', r`$f(x) = \sqrt{x - 1}$, $g(x) = x - 5$.`);
must(xs16.filter((x) => Number.isFinite(aF(x))).every((x) => x >= 1) && xs16.filter((x) => Number.isFinite(aF(x) / aG(x))).every((x) => x >= 1 && x !== 5) && aF(10) === 3 && aG(10) === 5, 'WE3');
const cf = (x) => 2 * x + 1, cg = (x) => x * x;
must(cg(cf(2)) === 25 && cf(cg(2)) === 9 && xs16.some((x) => cg(cf(x)) !== cf(cg(x))), 'composition');
const compFlow = flow('LR', [['x', 'Input $x = 2$'], ['f', r`$f(x) = 2x + 1$ gives $5$`], ['g', r`$g(x) = x^2$ gives $25$`], ['o', r`$(g \circ f)(2) = 25$`]], [['x', 'f'], ['f', 'g'], ['g', 'o']], 'Flow diagram of a composition: the input 2 goes through f of x equal 2 x plus 1 to give 5, then through g of x equal x squared to give 25, so g after f at 2 is 25.', r`$g \circ f$: apply $f$ first, then $g$.`);
const summary2 = flow('LR', [['f', r`Function $f : A \to B$`], ['g', 'Graphs: constant, polynomial, rational, modulus, signum, greatest integer'], ['a', 'Algebra: $f \\pm g$, $fg$, $f/g$ on common domain'], ['c', r`Composition $g \circ f$`]], [['f', 'g'], ['g', 'a'], ['a', 'c']], 'Summary flow: a function gives each input one output; real functions are studied through their graphs; they can be added, subtracted, multiplied and divided on the common domain; and composed.', 'Functions: definition, graphs, algebra.');

// ================================================================ deck 1
const d1 = deck({
  part: 1,
  title: 'Relations and Functions — Part 1: Cartesian products and relations',
  goals: ['Write ordered pairs and decide when two ordered pairs are equal', 'Form the Cartesian product of two sets and count its elements', 'Describe a relation from a set A to a set B', 'Find the domain, codomain and range of a relation', 'Count the relations from one finite set to another'],
  slides: [
    sl('title', 'Relations and Functions, Part 1: Pairs and relations', { b: 'A canteen menu pairs every snack with every drink. What does that look like in mathematics?', v: canteen, n: 'Welcome to Class Eleven mathematics. Picture a canteen that sells three snacks and two drinks. A combo is one snack together with one drink, and the menu lists every possible combo. Each combo is an ordered pair, and the whole menu is a Cartesian product. In this part you will build products, define relations as pieces of a product, and learn to read off domain and range.' }),
    sl('concept', 'What you will be able to do', { ul: ['Write and compare **ordered pairs**', 'Form the **Cartesian product** $A \\times B$ and count it', 'Define a **relation** as a subset of $A \\times B$', 'Find **domain**, **codomain** and **range**', 'Count the **relations** between small sets'], n: 'Here are your goals. You will learn when two ordered pairs are equal, how to list a Cartesian product and count its elements, and what a relation is. You will then practise finding the domain, codomain and range, and counting how many different relations exist between two small sets. Questions on these appear as one-mark objectives and two or three mark short answers.' }),
    sl('concept', 'Ordered pairs', { b: r`An **ordered pair** $(a, b)$ has a first entry and a second entry. $(a, b) = (c, d)$ exactly when $a = c$ **and** $b = d$.`, v: pOrder, n: 'An ordered pair is two entries written in a fixed order. The pair two comma five is not the same as five comma two, just as the point two across and five up is different from the point five across and two up. Two ordered pairs are equal only when both the first entries match and the second entries match.' }),
    sl('concept', 'The Cartesian product', { b: r`$A \times B = \{(a, b) : a \in A,\ b \in B\}$: every element of $A$ paired with every element of $B$, first entry from $A$.`, v: gridTable, m: [r`A \times B = \{(a, b) : a \in A,\ b \in B\}`], n: 'The Cartesian product of A and B is the set of all ordered pairs whose first entry comes from A and whose second entry comes from B. A grid table helps: put the elements of A down the side, the elements of B across the top, and each cell is one pair. With three rows and two columns there are six pairs.' }),
    sl('diagram', 'A product as points on a grid', { b: 'Plotted, $\\{1, 2, 3\\} \\times \\{4, 5\\}$ is a rectangular lattice of points.', v: pGrid, n: 'When the sets contain numbers, each ordered pair is a point in the plane. Here the first set is one, two, three and the second is four, five. The six pairs form a neat lattice with three columns and two rows. Notice that the real plane itself is the Cartesian product of the real line with itself.' }),
    sl('concept', 'A × B and B × A are different', { b: r`$A \times B = B \times A$ only when $A = B$ (or one set is empty). Otherwise the products have the **same size** but **different elements**.`, v: abBa, n: 'Because order matters, A cross B and B cross A are usually different sets. For A equal to one, two and B equal to three, four, both products have four pairs, but they share no pair at all. The first list has pairs like one comma three; the second has three comma one. Same size, different elements. Always keep the order of the sets straight.' }),
    sl('concept', 'Counting a product', { b: r`If $n(A) = p$ and $n(B) = q$, then $n(A \times B) = pq$. In particular $n(A \times A) = p^2$.`, v: countTable, m: [r`n(A \times B) = n(A) \times n(B)`], n: 'Each of the p elements of the first set pairs with each of the q elements of the second, so the product has p times q elements. The table was made by listing the pairs. When the two sets are the same, the product has p squared elements. If either set is empty, the product is empty.' }),
    sl('check', 'Quick check: size of a product', { b: 'A set has four elements and another has five. How large is the Cartesian product?', chk: 'm02', n: 'Multiply the two sizes. Do not add them.' }),
    sl('example', 'Worked example 1: products and equal pairs', { b: r`$A = \{2, 3\}$ and $B = \{1, 4, 5\}$. List $A \times B$, $B \times A$ and $A \times A$. Then find $x$ and $y$ if $(x + 1,\ 2y - 3) = (4,\ 7)$.`, ul: [r`**Counts —** $n(A \times B) = 2 \times 3 = 6$, $n(B \times A) = 6$, $n(A \times A) = 4$`, r`**Lists —** as in the table: first entry from the first set`, r`**Equal pairs —** $x + 1 = 4 \Rightarrow x = 3$ and $2y - 3 = 7 \Rightarrow y = 5$`], v: we1Table, n: 'List each product by taking every first entry with every second entry. A cross B and B cross A each have six pairs and A cross A has four. For the equation, equal ordered pairs have equal entries in matching positions. So x plus one equals four gives x equal to three, and two y minus three equals seven gives y equal to five.' }),
    sl('concept', 'What is a relation?', { b: r`A **relation** $R$ from $A$ to $B$ is any **subset** of $A \times B$. We write $x\,R\,y$ when $(x, y) \in R$.`, v: relArrows, m: [r`R \subseteq A \times B`], n: 'A relation from A to B picks out some of the pairs of the product. It can be a few pairs, all of them, or none. In the arrow diagram, each arrow is one pair. Here the rule is y equals two x minus one: one goes to one, two goes to three, three goes to five, and four goes to seven. The element nine in the second set receives no arrow.' }),
    sl('concept', 'Domain, codomain and range', { b: r`**Domain:** all first entries. **Codomain:** the whole set $B$. **Range:** the second entries that actually occur, so range $\subseteq$ codomain.`, v: drTable, n: 'Three sets describe a relation. The domain is the set of first entries. The codomain is the whole target set B, whether or not every element is used. The range is the set of second entries that really occur, so it can be smaller than the codomain. In our relation the range is one, three, five, seven, and nine is left out.' }),
    sl('concept', 'Four ways to describe a relation', { b: 'The same relation can be given as a **roster**, a **rule**, an **arrow diagram** or a **table**. Be ready to switch between them.', v: waysTable, n: 'Questions give a relation in different forms. You can list the pairs, which is the roster form. You can state a rule in set-builder form. You can draw arrows between two boxes. Or you can tabulate the first and second entries side by side. Practise moving between these forms, because converting to a list of pairs makes the domain and range easy to read.' }),
    sl('check', 'Quick check: pairs of a relation', { b: 'How many ordered pairs does the relation x less than y have, from {1, 2, 3} to {2, 3, 4}?', chk: 'm09', n: 'Go through each first entry and count the second entries that are larger.' }),
    sl('example', 'Worked example 2: from a rule to a list', { b: r`$A = \{0, 1, 2, 3, 4\}$, $B = \{-2, -1, 0, 1, 2, 3, 4\}$ and $R = \{(x, y) : y = x^2 - 3x\}$. Write $R$, its domain and its range.`, ul: [r`**Compute —** $y = 0, -2, -2, 0, 4$ for $x = 0, 1, 2, 3, 4$; all lie in $B$`, r`**Roster —** $R = \{(0, 0), (1, -2), (2, -2), (3, 0), (4, 4)\}$`, r`**Domain —** $\{0, 1, 2, 3, 4\}$; **range —** $\{-2, 0, 4\}$`], v: we2Table, n: 'Substitute each element of A into the rule and check that the answer lies in B. The values are zero, minus two, minus two, zero and four, all inside B. So the relation has five pairs. Every element of A is a first entry, so the domain is all of A. The second entries, written once each, give the range: minus two, zero and four.' }),
    sl('concept', 'Counting relations', { b: r`$A \times B$ has $pq$ pairs and a relation is any subset of it, so there are $2^{pq}$ relations from $A$ to $B$.`, v: countRelTable, m: [r`\text{number of relations from } A \text{ to } B = 2^{pq}`], n: 'To build a relation, decide for each pair of the product whether it is in or out. With p times q pairs, that is two choices each, giving two to the power p q relations. The table was built by listing every subset. From a set of two to a set of three elements there are sixty-four relations. Remember to count subsets, not pairs.' }),
    sl('check', 'Quick check: a false claim', { b: 'True or false: for two different non-empty sets, A cross B equals B cross A.', chk: 'tf1', n: 'Try the smallest case: one set holds the number one and the other holds the number two.' }),
    sl('example', 'Worked example 3: reading an arrow diagram', { b: r`The diagram shows a relation from $X = \{a, b, c, d\}$ to $Y = \{1, 2, 3\}$. Write the pairs, the domain and the range.`, ul: [r`**Pairs —** $(a, 1), (a, 2), (b, 2), (d, 3)$`, r`**Domain —** $\{a, b, d\}$: the element $c$ has no arrow, so it is **not** in the domain`, r`**Range —** $\{1, 2, 3\}$, which here equals $Y$`], v: we3Arrows, n: 'Read each arrow as a pair. A has two arrows, to one and to two. B has one arrow to two. D has one arrow to three. C has no arrow. The domain is only the set of first entries that appear, so it is A, B, D, and C is left out. The range is one, two, three. Notice that the domain can be smaller than the first set.' }),
    sl('check', 'Quick check: count a product', { b: 'Count the elements of the product of the primes below twelve and the multiples of three between zero and twenty.', chk: 'n01', n: 'Write out each set first, count them, then multiply.' }),
    sl('summary', 'Summary', { ul: [r`Ordered pairs: $(a, b) = (c, d)$ iff $a = c$ and $b = d$`, r`$A \times B$: all pairs $(a, b)$; $n(A \times B) = pq$`, r`$A \times B \ne B \times A$ in general`, r`Relation from $A$ to $B$: a subset of $A \times B$; $2^{pq}$ of them`, 'Domain = first entries; codomain = $B$; range = second entries used'], v: summary1, n: 'To sum up. Ordered pairs have a fixed order. The Cartesian product collects all pairs, and it has p times q elements. A relation is any subset of the product, and there are two to the power p q of them. For each relation, the domain holds the first entries, the codomain is the whole second set, and the range holds the second entries that occur.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Product listing (1–2 marks):** correct pairs, correct order, correct count', '**Relation from a rule (2–3 marks):** roster form 1, domain and range 1–2', '**Equal ordered pairs (1–2 marks):** compare entries position by position', '**Mistake:** writing $B \\times A$ when $A \\times B$ is asked', '**Mistake:** giving the codomain as the range', '**Mistake:** counting relations as $pq$ instead of $2^{pq}$'], n: 'For product questions, marks go for the right pairs in the right order and the right count. For relations given by a rule, write the roster form first, then read off the domain and the range. Watch three common slips: reversing the order of the product, giving the whole codomain as the range, and counting the pairs instead of the subsets when asked for the number of relations.' }),
  ],
});

// ================================================================ deck 2
const d2 = deck({
  part: 2,
  title: 'Relations and Functions — Part 2: Functions and their graphs',
  goals: ['Decide whether a relation is a function, and find domain and range', 'Recognise and sketch the standard real functions', 'Evaluate functions such as the signum and greatest integer functions', 'Add, subtract, multiply and divide real functions with their domains', 'Compose two functions (formative only)'],
  slides: [
    sl('title', 'Relations and Functions, Part 2: Functions', { b: 'A function is a rule that gives exactly one output for every allowed input.', v: machine, n: 'Welcome to part two. Think of a function as a machine. You put in an input, the machine applies a fixed rule, and exactly one output comes out. In this part you will meet functions as a special kind of relation, learn how to find their domain and range, study the graphs of the standard real functions, and learn to combine functions by adding, multiplying and dividing them.' }),
    sl('concept', 'What you will be able to do', { ul: ['Tell a **function** from a relation that is not one', 'Find **domain** and **range** of real functions', 'Know the graphs of **constant, identity, polynomial, rational, modulus, signum** and **greatest integer** functions', 'Use $f + g$, $f - g$, $fg$, $f/g$ with their domains', 'Compose two functions (formative only)'], n: 'Here are your goals for part two. You will recognise functions, find their domains and ranges, and know the shapes of the standard graphs. You will also do algebra with functions and find the domain of each combination. Composition of functions is included here for your own understanding; the board does not assess it in the annual paper.' }),
    sl('concept', 'A function is a special relation', { b: r`A relation $f$ from $A$ to $B$ is a **function** if **every** $x \in A$ has **exactly one** image $f(x) \in B$. So the domain is all of $A$.`, v: fnArrows, n: 'A function is a relation in which every element of the domain has exactly one arrow leaving it. Two different inputs may share an output, as minus two and two both go to four here. The codomain may have unused elements, like nine. The range is the set of outputs actually used. For the squaring function on this set, the range is one and four.' }),
    sl('diagram', 'When a relation is not a function', { b: 'Two failures: an input with **two** images, or an input with **none**.', v: notFn, n: 'There are two ways for a relation to fail the test. In this diagram the element one has two arrows, so it has two different images, which is not allowed. The element three has no arrow at all, so it has no image, which is also not allowed. Notice that the element two is fine: one arrow only.' }),
    sl('diagram', 'The vertical line test', { b: 'If a vertical line meets a graph at **two** points, the graph is **not** the graph of a function of $x$.', v: pVert, n: 'For graphs, there is a quick test. Draw a vertical line. If it ever meets the graph in two points, then one input has two outputs, and the graph is not a function of x. The sideways parabola x equals y squared fails: the line x equals four meets it at the points four comma two and four comma minus two.' }),
    sl('concept', 'Domain and range of a real function', { b: r`**Domain:** every real $x$ for which the rule makes sense (no division by zero, no square root of a negative). **Range:** solve $y = f(x)$ for $x$ and see which $y$ are possible.`, v: drExamples, n: 'For a real function, the domain is every real number for which the rule works. Watch for denominators that are zero and square roots of negative numbers. To find the range, write y equals f of x, solve for x, and see which values of y allow a real solution. The table shows three examples, each checked by testing many values.' }),
    sl('concept', 'Constant and identity functions', { b: r`**Constant:** $f(x) = c$, range $\{c\}$. **Identity:** $f(x) = x$, range $\mathbb{R}$. Both have domain $\mathbb{R}$.`, v: pConst, n: 'The constant function gives the same output, here three, for every input, so its graph is a horizontal line and its range has just one element. The identity function returns its input unchanged, so its graph is the diagonal line, and the range is all real numbers. Here the two lines meet at the point three comma three.' }),
    sl('concept', 'Polynomial functions', { b: r`$f(x) = a_0 + a_1 x + \cdots + a_n x^n$ has domain $\mathbb{R}$. $x^2$ has range $[0, \infty)$; $x^3$ has range $\mathbb{R}$.`, v: pPoly, n: 'A polynomial function is built from powers of x, so it works for every real input. The square function makes a U shape and never goes below zero, so its range is zero upward. The cube function rises from the lower left to the upper right, taking every real value, so its range is all real numbers. Both pass through the origin and the point one comma one.' }),
    sl('concept', 'Rational functions', { b: r`$f(x) = \dfrac{p(x)}{q(x)}$ is defined where $q(x) \ne 0$. For $f(x) = \dfrac{1}{x}$: domain $\mathbb{R} - \{0\}$, range $\mathbb{R} - \{0\}$.`, v: pRat, n: 'A rational function is a fraction of two polynomials, and it is undefined wherever the denominator is zero. The reciprocal function one over x has two branches, one for positive x and one for negative x, with nothing at x equal to zero. It never takes the value zero either, so both its domain and its range are all real numbers except zero.' }),
    sl('check', 'Quick check: domain of a rational function', { b: 'Find the domain of the function x plus one over x squared minus four.', chk: 'm13', n: 'Which values of x make the denominator zero?' }),
    sl('concept', 'The modulus function', { b: r`$|x| = x$ for $x \ge 0$ and $-x$ for $x < 0$. Domain $\mathbb{R}$, range $[0, \infty)$.`, v: pAbs, n: 'The modulus function returns the distance of a number from zero. For zero and positive numbers it leaves them alone; for negative numbers it flips the sign. Its graph is a V with the corner at the origin. The domain is all real numbers, and because distances are never negative, the range is zero and upward.' }),
    sl('concept', 'The signum function', { b: r`$\operatorname{sgn}(x) = 1$ if $x > 0$, $0$ if $x = 0$, $-1$ if $x < 0$. Range $\{-1, 0, 1\}$.`, v: pSgn, n: 'The signum function reports only the sign of a number. It gives one for positive numbers, minus one for negative numbers, and zero at zero. Its graph is two flat half-lines with a single point at the origin. The range has just three elements: minus one, zero and one. The domain is all the real numbers.' }),
    sl('concept', 'The greatest integer function', { b: r`$[x]$ is the greatest integer **not exceeding** $x$. E.g. $[2.9] = 2$, $[-0.4] = -1$. Domain $\mathbb{R}$, range $\mathbb{Z}$.`, v: pFloor, n: 'The greatest integer function rounds a number down to the nearest integer at or below it. So two point nine becomes two, and minus zero point four becomes minus one, not zero. Its graph is a staircase: flat between consecutive integers, jumping up by one at each integer. The domain is all real numbers, and the range is the set of all integers.' }),
    sl('check', 'Quick check: floor and signum', { b: 'Evaluate the greatest integer of minus two point three, minus the signum of minus four, plus the greatest integer of one point eight.', chk: 'm16', n: 'Find each value separately, and be careful with the minus sign.' }),
    sl('concept', 'Exponential and logarithmic functions', { b: r`$2^x$: domain $\mathbb{R}$, range $(0, \infty)$. $\log_2 x$: domain $(0, \infty)$, range $\mathbb{R}$. Their graphs mirror each other in $y = x$.`, v: pExp, n: 'Two more graphs appear in the syllabus. The exponential function two to the power x is defined for every real x and is always positive. The logarithm to base two is defined only for positive x and takes every real value. Their graphs are mirror images in the line y equals x. You only need to recognise their shapes and their domains and ranges here.' }),
    sl('example', 'Worked example 1: domain and range of a root', { b: r`Find the domain and range of $f(x) = \sqrt{9 - x^2}$.`, ul: [r`**Domain —** $9 - x^2 \ge 0 \Rightarrow x^2 \le 9 \Rightarrow -3 \le x \le 3$`, r`**Values —** $0 \le 9 - x^2 \le 9$, so $0 \le f(x) \le 3$`, r`**Every value reached —** $y \in [0, 3]$ comes from $x = \sqrt{9 - y^2}$`, r`**Answer —** domain $[-3, 3]$, range $[0, 3]$`], v: pSemi, n: 'The square root needs a non-negative number inside, so nine minus x squared must be at least zero. That means x lies between minus three and three. Inside this interval the expression ranges from zero up to nine, so the square root ranges from zero up to three. Every value from zero to three is reached. The graph is the upper half of a circle of radius three.' }),
    sl('check', 'Quick check: is it a function?', { b: 'Which of these relations from {1, 2, 3} to {a, b} is a function?', chk: 'm11', n: 'Every element of the first set needs exactly one arrow.' }),
    sl('example', 'Worked example 2: a modulus graph', { b: r`Sketch $f(x) = |x - 2| + 1$ and find its range.`, ul: [r`**Shift —** the graph of $|x|$ moved $2$ units right and $1$ unit up`, r`**Vertex —** $(2, 1)$, the lowest point`, r`**Pieces —** $x - 1$ for $x \ge 2$; $3 - x$ for $x < 2$`, r`**Range —** $|x - 2| \ge 0$, so $f(x) \ge 1$: $[1, \infty)$`], v: pAbs2, n: 'Start from the V-shaped graph of the modulus function. Subtracting two inside the modulus shifts it two units to the right, and adding one outside shifts it one unit up. The corner moves from the origin to two comma one, which is the lowest point. Since the modulus is never negative, the function never goes below one. The range is one and upward.' }),
    sl('concept', 'Algebra of real functions', { b: r`On the **common domain** $D_f \cap D_g$: $(f \pm g)(x) = f(x) \pm g(x)$, $(fg)(x) = f(x)g(x)$. For $\dfrac{f}{g}$ also remove the $x$ with $g(x) = 0$.`, v: algTable, n: 'Two real functions can be added, subtracted and multiplied wherever both are defined, that is, on the intersection of their domains. For a quotient you must also remove every point where the divisor is zero. The table uses the square root function and x minus four. At x equal nine, the sum is eight, the difference minus two, the product fifteen, and the quotient three fifths.' }),
    sl('example', 'Worked example 3: domains and values', { b: r`$f(x) = \sqrt{x - 1}$ and $g(x) = x - 5$. Find the domains of $f + g$ and $\dfrac{f}{g}$, and the values of $(fg)(10)$ and $\left(\dfrac{f}{g}\right)(10)$.`, ul: [r`**Domain of $f$ —** $x \ge 1$; of $g$ — all reals`, r`**$f + g$ —** common domain $[1, \infty)$`, r`**$f/g$ —** also $g(x) = x - 5 \ne 0$, so $[1, \infty) - \{5\}$`, r`**At $x = 10$ —** $f(10) = 3$, $g(10) = 5$, so $(fg)(10) = 15$ and $(f/g)(10) = \dfrac{3}{5}$`], v: we3Table, n: 'First find the domain of each function: the root needs x at least one, and the linear function works everywhere. The sum lives on the common domain, one and upward. The quotient must also avoid x equal to five, where the divisor vanishes. At x equal ten the root gives three and the linear function gives five, so the product is fifteen and the quotient is three fifths.' }),
    sl('check', 'Quick check: product of functions', { b: 'For f of x equal two x minus one and g of x equal x squared plus one, find the product function at three.', chk: 'm19', n: 'Evaluate each function at three, then multiply.' }),
    sl('concept', 'Composition of functions (formative only)', { b: r`$(g \circ f)(x) = g(f(x))$: apply $f$ first, then $g$. In general $g \circ f \ne f \circ g$. *Taught for understanding; not assessed in the annual paper.*`, v: compFlow, n: 'You can feed the output of one function into another. The composition g after f applies f first and then g. With f of x equal two x plus one and g the squaring function, the input two becomes five and then twenty-five. In general the order matters: applying g first and then f at two gives nine instead. This topic is for your understanding and is not assessed in the annual paper.' }),
    sl('summary', 'Summary', { ul: ['Function: every input has **exactly one** output; vertical line test', 'Domain: where the rule works; range: solve $y = f(x)$', 'Standard graphs: constant, identity, polynomial, rational, modulus, signum, greatest integer, exponential, logarithmic', r`$f \pm g$, $fg$ on $D_f \cap D_g$; $f/g$ also needs $g(x) \ne 0$`, r`$g \circ f$: first $f$, then $g$ (formative only)`], v: summary2, n: 'To sum up. A function gives every allowed input exactly one output. Find the domain by excluding division by zero and square roots of negatives, and find the range by solving for x. Know the shapes of the standard graphs. Combine functions on the common domain, removing zeros of the divisor for quotients. Composition applies one function after another, and the order matters.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Domain (1 mark):** state excluded values or the interval clearly', '**Range (1–2 marks):** show the solving step $x = \\dots$ in terms of $y$', '**Sketch (2–3 marks):** key points, shape, open or closed ends', '**Mistake:** forgetting to exclude zeros of the divisor in $f/g$', '**Mistake:** $[-0.4] = 0$ instead of $-1$', '**Mistake:** giving a codomain instead of the range'], n: 'For domain questions, name the excluded values or write the interval clearly. For range questions, show the step where you solve for x in terms of y. For sketches, mark the key points and the shape. The common mistakes are forgetting to remove the zeros of the divisor in a quotient, rounding minus zero point four up to zero instead of down to minus one, and confusing the range with the codomain.' }),
  ],
});

// ================================================================ notes
const notes = {
  unit: 'cbse-11-mathematics-ch02', version: 1, title: 'Relations and Functions — chapter notes', language: 'en',
  sections: [
    { heading: '1. Ordered pairs and the Cartesian product', body_md: r`An **ordered pair** $(a, b)$ has a first and a second entry. $(a, b) = (c, d)$ exactly when $a = c$ and $b = d$.\n\nThe **Cartesian product** $A \times B = \{(a, b) : a \in A,\ b \in B\}$.\n\n- $A \times B \ne B \times A$ in general (equal only if $A = B$ or one is empty).\n- If $A$ or $B$ is empty, so is $A \times B$.\n- $\mathbb{R} \times \mathbb{R}$ is the coordinate plane.\n\nList a product with a grid table: elements of $A$ down the side, of $B$ across the top, each cell a pair.`, key_terms: [{ term: 'Ordered pair', definition_md: 'Two entries in a fixed order.' }, { term: 'Cartesian product', definition_md: r`All ordered pairs with first entry from $A$ and second from $B$.` }], formulas: [{ latex: r`(a, b) = (c, d) \iff a = c \text{ and } b = d`, label: 'Equal ordered pairs' }], visual: gridTable, visuals: [pOrder], topic_ids: [topic(1)] },
    { heading: '2. Counting a Cartesian product', body_md: r`If $n(A) = p$ and $n(B) = q$ then $n(A \times B) = pq$ and $n(A \times A) = p^2$.\n\nThe products $A \times B$ and $B \times A$ have the **same size** but, for $A \ne B$, **different elements**.\n\nPlotted on a grid, a product of two sets of numbers is a lattice of points; the pair $(a, b)$ is the point $a$ across and $b$ up.`, key_terms: [{ term: 'n(A × B)', definition_md: r`The number of elements of the product: $n(A)\,n(B)$.` }], formulas: [{ latex: r`n(A \times B) = n(A) \cdot n(B)`, label: 'Counting a product' }], visual: countTable, visuals: [pGrid, abBa], topic_ids: [topic(1)] },
    { heading: '3. Relations', body_md: r`A **relation** from $A$ to $B$ is any subset of $A \times B$; $x\,R\,y$ means $(x, y) \in R$. A relation on $A$ is a subset of $A \times A$.\n\nA relation can be described by a **roster** (list of pairs), a **rule** (set-builder), an **arrow diagram** or a **table**. Convert to a list of pairs first: everything else is then easy to read.\n\nExample: $y = x^2 - 3x$ on $\{0, 1, 2, 3, 4\}$ gives $\{(0, 0), (1, -2), (2, -2), (3, 0), (4, 4)\}$.`, key_terms: [{ term: 'Relation from A to B', definition_md: r`A subset of $A \times B$.` }, { term: 'Roster form', definition_md: 'Listing the ordered pairs one by one.' }], formulas: [{ latex: r`R \subseteq A \times B`, label: 'Relation' }], visual: relArrows, visuals: [waysTable, we2Table], topic_ids: [topic(2)] },
    { heading: '4. Domain, codomain and range', body_md: r`For a relation $R$ from $A$ to $B$:\n\n- **Domain** = set of all first entries (a subset of $A$).\n- **Codomain** = the whole set $B$.\n- **Range** = set of second entries that occur (a subset of $B$).\n\nElements of $A$ with no arrow are **not** in the domain; elements of $B$ with no arrow are in the codomain but not in the range.\n\nNumber of relations from $A$ to $B$: $2^{pq}$ (each of the $pq$ pairs is in or out). Non-empty relations: $2^{pq} - 1$.`, key_terms: [{ term: 'Domain', definition_md: 'First entries of the pairs.' }, { term: 'Codomain', definition_md: r`The target set $B$.` }, { term: 'Range', definition_md: 'Second entries that actually occur.' }], formulas: [{ latex: r`\text{relations from } A \text{ to } B = 2^{pq}`, label: 'Counting relations' }], visual: drTable, visuals: [countRelTable, we3Arrows], topic_ids: [topic(2)] },
    { heading: '5. Functions', body_md: r`A relation $f$ from $A$ to $B$ is a **function** if every $x \in A$ has **exactly one** image $f(x) \in B$. Then the domain is $A$, the codomain is $B$ and the range is $\{f(x) : x \in A\} \subseteq B$.\n\nFailures: an element with **two** arrows or with **none**. Two different inputs may share an output.\n\n**Vertical line test:** a graph is a function of $x$ if every vertical line meets it at most once.\n\nBetween finite sets with $p$ and $q$ elements there are $q^p$ functions among the $2^{pq}$ relations.`, key_terms: [{ term: 'Function', definition_md: r`A relation giving every element of the domain exactly one image.` }, { term: 'Image', definition_md: r`The output $f(x)$ for an input $x$.` }], formulas: [{ latex: r`\text{functions from } A \text{ to } B = q^{p}`, label: 'Counting functions' }], visual: fnArrows, visuals: [notFn, pVert], topic_ids: [topic(3)] },
    { heading: '6. Domain and range of real functions', body_md: r`A **real function** has domain and range inside $\mathbb{R}$. **Domain:** all real $x$ where the rule works: no zero denominator, no root of a negative, $x > 0$ for a logarithm.\n\n**Range:** write $y = f(x)$, solve for $x$ in terms of $y$, and keep the $y$ for which a real $x$ in the domain exists.\n\nExamples: $\sqrt{x - 2}$: domain $[2, \infty)$, range $[0, \infty)$. $\dfrac{1}{x - 3}$: domain and range both $\mathbb{R}$ minus one point. $\sqrt{9 - x^2}$: domain $[-3, 3]$, range $[0, 3]$.\n\nTwo functions are **equal** only when their domains and rules both agree.`, key_terms: [{ term: 'Real function', definition_md: 'A function whose domain and range are sets of real numbers.' }], formulas: [{ latex: r`y = f(x) \;\Rightarrow\; x = \dots \text{ in terms of } y`, label: 'Finding the range' }], visual: drExamples, visuals: [pSemi], topic_ids: [topic(3)] },
    { heading: '7. Standard real functions and their graphs', body_md: r`- **Constant** $f(x) = c$: horizontal line, range $\{c\}$. **Identity** $f(x) = x$: range $\mathbb{R}$.\n- **Polynomial:** domain $\mathbb{R}$; $x^2$ has range $[0, \infty)$, $x^3$ has range $\mathbb{R}$.\n- **Rational** $\dfrac{p(x)}{q(x)}$: domain excludes $q(x) = 0$; $\dfrac{1}{x}$ has domain and range $\mathbb{R} - \{0\}$.\n- **Modulus** $|x|$: V-shaped, range $[0, \infty)$. $|x - a| + b$ has its corner at $(a, b)$.\n- **Signum:** $1, 0, -1$; range $\{-1, 0, 1\}$.\n- **Greatest integer** $[x]$: staircase, range $\mathbb{Z}$. $[2.9] = 2$, $[-0.4] = -1$.\n- **Exponential** $2^x$: range $(0, \infty)$. **Logarithm** $\log_2 x$: domain $(0, \infty)$, range $\mathbb{R}$; mirror images in $y = x$.`, key_terms: [{ term: 'Modulus function', definition_md: r`$|x|$: distance of $x$ from $0$.` }, { term: 'Signum function', definition_md: r`$1, 0$ or $-1$ according to the sign of $x$.` }, { term: 'Greatest integer function', definition_md: r`$[x]$: greatest integer not exceeding $x$.` }], formulas: [{ latex: r`|x| = \begin{cases} x, & x \ge 0 \\ -x, & x < 0 \end{cases}`, label: 'Modulus' }, { latex: r`[x] = n \iff n \le x < n + 1,\ n \in \mathbb{Z}`, label: 'Greatest integer' }], visual: pAbs, visuals: [pConst, pPoly, pRat, pSgn, pFloor, pExp, pAbs2], topic_ids: [topic(3)] },
    { heading: '8. Algebra of real functions and composition', body_md: r`On the common domain $D_f \cap D_g$:\n\n- $(f + g)(x) = f(x) + g(x)$ and $(f - g)(x) = f(x) - g(x)$.\n- $(fg)(x) = f(x)\,g(x)$ and $(cf)(x) = c\,f(x)$.\n- $\left(\dfrac{f}{g}\right)(x) = \dfrac{f(x)}{g(x)}$ with the $x$ where $g(x) = 0$ removed.\n\nExample: $f(x) = \sqrt{x}$, $g(x) = x - 4$: $f/g$ has domain $[0, \infty) - \{4\}$.\n\n**Composition (formative only, not assessed in the annual paper):** $(g \circ f)(x) = g(f(x))$. In general $g \circ f \ne f \circ g$: for $f(x) = 2x + 1$, $g(x) = x^2$, $(g \circ f)(2) = 25$ but $(f \circ g)(2) = 9$.`, key_terms: [{ term: 'Common domain', definition_md: r`$D_f \cap D_g$, where both functions are defined.` }, { term: 'Composite function', definition_md: r`$g \circ f$: apply $f$, then $g$.` }], formulas: [{ latex: r`\left(\frac{f}{g}\right)(x) = \frac{f(x)}{g(x)}, \quad g(x) \ne 0`, label: 'Quotient' }, { latex: r`(g \circ f)(x) = g\bigl(f(x)\bigr)`, label: 'Composition' }], visual: algTable, visuals: [we3Table, compFlow], topic_ids: [topic(4), topic(5)] },
  ],
  exam_tips_md: r`**How marks are awarded**\n- *Cartesian product (1–2 marks):* all pairs, correct order, correct count $pq$.\n- *Relation from a rule (2–3 marks):* roster form 1, domain 1, range 1.\n- *Is it a function? (1–2 marks):* test every element of the first set for exactly one arrow; quote the failing element.\n- *Domain and range (2–3 marks):* excluded values or an interval for the domain; solve $y = f(x)$ for the range.\n- *Graph (2–3 marks):* shape, key points, corners and jumps.\n- *Algebra of functions (2–3 marks):* expression, common domain, zeros of the divisor removed.\n\n**Common mistakes**\n1. Writing $B \times A$ when $A \times B$ is asked, or assuming they are equal.\n2. Giving the codomain as the range.\n3. Counting relations as $pq$ instead of $2^{pq}$.\n4. Leaving out an element of the domain that has no arrow, or putting it in.\n5. Forgetting to remove the zeros of $g$ in the domain of $f/g$.\n6. $[-0.4] = 0$: the greatest integer not exceeding $-0.4$ is $-1$.\n7. Concluding $\dfrac{x^2 - 4}{x - 2}$ and $x + 2$ are the same function (their domains differ).\n8. Composition and exponential-logarithmic graphs are light topics: composition is formative only.`,
  status: 'draft', provenance: d1.provenance,
};

